var e=(e,t)=>{let n=e.find(e=>e.url===t),r=document.getElementById(`id_branch`);for(;r.options.length>0;)r.remove(0);let i=document.getElementById(`id_branch`);n.branches.forEach(e=>{let t=e===`master`||e===`main`;i.append(new Option(e,e,t,t))})},t=JSON.parse(document.getElementById(`reposWithBranches`).textContent);document.getElementById(`id_repo`)?.addEventListener(`change`,n=>{e(t,n.target.value)});